'use strict';
(async()=>{const panel=document.querySelector('#panel');let data;try{const res=await fetch('data.json');if(!res.ok)throw Error();data=await res.json()}catch(e){panel.innerHTML='<div class="panel"><p>Experiment data could not be loaded. Please reopen this page from the Atlas.</p></div>';return}let tab=['parents','actors','access','persistence'].includes(location.hash.slice(1))?location.hash.slice(1):'parents',credit='.2',demand='1.4',pressure='.12',h=0,e=0,s=0,access='access_exclusion',memory='restored_slow_switch';const pct=x=>`${(Number(x)*100).toFixed(1)}%`,num=x=>Number(x).toFixed(2),metric=(label,value,bar)=>`<div class="metric"><div class="metric-top"><span>${label}</span><strong>${value}</strong></div>${bar===undefined?'':`<div class="bar"><i style="width:${Math.max(0,Math.min(100,100*Number(bar)))}%"></i></div>`}</div>`,select=(id,label,values,current)=>`<label for="${id}">${label}<select id="${id}">${values.map(([v,l])=>`<option value="${v}" ${v==current?'selected':''}>${l}</option>`).join('')}</select></label>`,ref=(name)=>data.tilly.find(x=>x.arm===name),layout=(k,title,description,controls,result)=>`<div class="panel"><div><div class="kicker">${k}</div><h3>${title}</h3><p>${description}</p><div class="controls">${controls}</div></div><div class="results">${result}</div></div>`;
function render(){document.querySelectorAll('[role=tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));if(tab==='parents'){let a=data.parent.find(x=>x.credit==Number(credit)&&x.demand==Number(demand)&&x.pressure==Number(pressure)),b=data.parent.find(x=>x.credit==Number(credit)&&x.demand==Number(demand)&&x.pressure===0);panel.innerHTML=layout('01 / HOUSEHOLD EMULATION','The pressure to keep up','Parents learn from the earnings of similar families. In this extension they also face an assumed penalty for aiming below the education their peers previously targeted.',select('credit','Household borrowing capacity',[[.2,'Lower borrowing'],[.8,'Higher borrowing']],credit)+select('demand','Formal-job demand setting',[[.6,'Lower demand'],[1.4,'Higher demand']],demand)+select('pressure','Peer-pressure setting',[[0,'None'],[.04,'Moderate'],[.12,'Stronger']],pressure),`<div class="result-title">Share of school-entry cohort · mean over 8 runs</div>${metric('Parents aiming for tertiary',pct(a.target_tertiary_all),a.target_tertiary_all)}${metric('Children completing tertiary',pct(a.share_tertiary),a.share_tertiary)}${metric('Poorest fifth completing tertiary',pct(a.complete_tertiary_q1),a.complete_tertiary_q1)}<div class="callout">Without peer pressure: ${pct(b.target_tertiary_all)} aim for tertiary and ${pct(b.share_tertiary)} complete it.</div><p class="note">The model records peer aspirations, not observed behavior. In some settings one seed drives much of the average; see the downloadable runs. Pressure is an assumption, not evidence that real parents behave this way.</p>`);['credit','demand','pressure'].forEach(id=>document.getElementById(id).onchange=ev=>{if(id==='credit')credit=ev.target.value;if(id==='demand')demand=ev.target.value;if(id==='pressure')pressure=ev.target.value;render()})}
else if(tab==='actors'){let x=data.triad.find(x=>+x.household_removed===h&&+x.employer_removed===e&&+x.state_removed===s);let choices=[[0,'Gain retained'],[1,'Gain removed']];panel.innerHTML=layout('02 / HOUSEHOLDS · EMPLOYERS · STATE','What happens when a support disappears?','Each actor has a reason to support the pipeline. Remove one or more gains to inspect how the simulated system responds.',select('h','Household formal-job gain',choices,h)+select('e','Employer credential screening',choices,e)+select('s','State fiscal gain',choices,s),`<div class="result-title">Last 20 simulated years · mean over 8 runs</div>${metric('Mean years of schooling',num(x.mean_years)+' years')}${metric('Completing tertiary',pct(x.share_tertiary),x.share_tertiary)}${metric('Firms using credentials',pct(x.cred_hire_share),x.cred_hire_share)}<div class="callout">The response to one removal depends on the other supports that remain.</div><p class="note">These are system-wide changes: the household intervention also changes wages and tax revenue; the state intervention changes its budget. The firm measure is not the share of hires.</p>`);['h','e','s'].forEach(id=>document.getElementById(id).onchange=ev=>{if(id==='h')h=+ev.target.value;if(id==='e')e=+ev.target.value;if(id==='s')s=+ev.target.value;render()})}
else if(tab==='access'){let x=ref(access),b=ref('baseline');panel.innerHTML=layout('03 / DURABLE INEQUALITY','Who gets into the queue?','The pipeline can expand while access to its rewards remains uneven. Compare the original simulation with imposed barriers and distributional changes.',select('access','Scenario', [['baseline','Baseline'],['access_exclusion','Exclude poorer applicants from credential-screened jobs'],['wage_withholding','Reduce formal wages by 20%'],['combined','Combine exclusion, wage reduction and imitation']],access),`<div class="result-title">Formal employment among labor-market entrants</div>${metric('Lowest income fifth',pct(x.q1_formal_mean),x.q1_formal_mean)}${metric('Highest income fifth',pct(x.q5_formal_mean),x.q5_formal_mean)}${metric('Mean years of schooling',num(x.mean_years_mean)+' years')}<div class="callout">Baseline formal employment: ${pct(b.q1_formal_mean)} for the lowest fifth and ${pct(b.q5_formal_mean)} for the highest fifth.</div><p class="note">The exclusion is imposed on credential-screened firms; other hiring remains possible. Income fifths are not persistent social identities. Wage reduction is a stress test, not a measurement of exploitation. Eight runs per setting.</p>`);document.getElementById('access').onchange=ev=>{access=ev.target.value;render()}}
else{let x=ref(memory);panel.innerHTML=layout('04 / ADAPTATION','Does the rule outlast its cause?','After year 90, access to referral networks returns. Compare ordinary switching with an assumed reluctance to change hiring methods.',select('memory','After networks return',[['networks_restored','Ordinary switching'],['restored_slow_switch','Slower switching']],memory),`<div class="result-title">Last 20 simulated years · mean over 8 runs</div>${metric('Firms using credentials',pct(x.cred_hire_share_mean),x.cred_hire_share_mean)}${metric('Mean years of schooling',num(x.mean_years_mean)+' years')}${metric('Lowest fifth in formal jobs',pct(x.q1_formal_mean),x.q1_formal_mean)}<div class="callout">Credential use and schooling can persist differently in the same simulated system.</div><p class="note">Slower switching is deliberately imposed. This is a model of organizational inertia—not independent proof of historical lock-in.</p>`);document.getElementById('memory').onchange=ev=>{memory=ev.target.value;render()}}}
document.querySelectorAll('[role=tab]').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.tab;history.replaceState(null,'','#'+tab);render()}));render();})();
